INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Firewall allein ausreichend, um ein Netzwerk vor Angriffen zu schützen?', 2, '[{"text": "Nein", "correct": true, "because": "Ergänzende Maßnahmen wie IDS nötig"}, {"text": "Ja", "correct": false, "because": "Schützt nicht vor internen Bedrohungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme schützt am besten vor Datenverlust durch Ransomware?', 3, '[{"text": "Regelmäßige Backups", "correct": true, "because": "Ermöglicht Wiederherstellung"}, {"text": "Starke Passwörter", "correct": false, "because": "Hilft, aber nicht primär"}, {"text": "Höhere Bandbreite", "correct": false, "because": "Irrelevant für Ransomware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden erhöhen die Sicherheit eines Servers?', 5, '[{"text": "Patch-Management", "correct": true, "because": "Schließt bekannte Schwachstellen"}, {"text": "Netzwerksegmentierung", "correct": true, "because": "Begrenzt Angriffsflächen"}, {"text": "Hohe CPU-Leistung", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Großer Arbeitsspeicher", "correct": false, "because": "Kein direkter Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Phishing zielt auf Nutzerdaten. b) Ein Virus verbreitet sich immer automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Viren brauchen oft Nutzeraktion"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht immer richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Absicherung eines WLANs?', 4, '[{"text": "Verschlüsselung", "correct": false, "because": "WPA3 ist essenziell"}, {"text": "MAC-Filter", "correct": false, "because": "Erhöht Kontrolle"}, {"text": "Router-Farbe", "correct": true, "because": "Irrelevant für Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein DDoS-Angriff immer die Datenintegrität gefährdet?', 2, '[{"text": "Nein", "correct": true, "because": "Zielt auf Verfügbarkeit"}, {"text": "Ja", "correct": false, "because": "Daten bleiben meist unberührt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wähle ich für sichere Datenübertragung?', 3, '[{"text": "HTTPS", "correct": true, "because": "Nutzt TLS für Verschlüsselung"}, {"text": "FTP", "correct": false, "because": "Unsicher, keine Verschlüsselung"}, {"text": "Telnet", "correct": false, "because": "Überträgt Daten im Klartext"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Passwort sicher?', 5, '[{"text": "Länge", "correct": true, "because": "Erschwert Brute-Force"}, {"text": "Sonderzeichen", "correct": true, "because": "Erhöht Komplexität"}, {"text": "Kurze Wörter", "correct": false, "because": "Leicht zu knacken"}, {"text": "Wiederholte Zeichen", "correct": false, "because": "Verringert Entropie"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Zwei-Faktor-Authentifizierung immer sicher ist und b) Passwörter regelmäßig geändert werden müssen. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "2FA kann umgangen werden, regelmäßige Änderung nicht immer nötig"}, {"text": "Beides stimmt", "correct": false, "because": "Beide Aussagen sind kontextabhängig"}, {"text": "Nur a) stimmt", "correct": false, "because": "2FA nicht absolut sicher"}, {"text": "Nur b) stimmt", "correct": false, "because": "Änderung nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein System vor SQL-Injection zu schützen?', 4, '[{"text": "Prepared Statements", "correct": false, "because": "Verhindern Injektionen"}, {"text": "Eingabevalidierung", "correct": false, "because": "Filtert schädliche Eingaben"}, {"text": "Schnelle Datenbank", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein VPN immer sicher?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Protokoll und Konfiguration"}, {"text": "Ja", "correct": false, "because": "Schwachstellen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen vor Social Engineering?', 4, '[{"text": "Schulungen", "correct": true, "because": "Sensibilisieren Mitarbeiter"}, {"text": "Richtlinien", "correct": true, "because": "Legen Verhaltensregeln fest"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Antivirenprogramme alle Bedrohungen abwehren. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Neue Malware kann unerkannt bleiben"}, {"text": "Ja", "correct": false, "because": "Kein 100%iger Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Absicherung einer Datenbank?', 3, '[{"text": "Berechtigungsmanagement", "correct": true, "because": "Begrenzt Zugriff"},       {"text": "Schnelle Hardware", "correct": false, "because": "Kein primärer Sicherheitsfaktor"}, {"text": "Tägliche Neustarts", "correct": false, "because": "Nicht sicherheitsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein IDS erkennt Angriffe. b) Ein IPS blockiert sie.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "IDS überwacht, IPS handelt"}, {"text": "Nur a) stimmt", "correct": false, "because": "IPS ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "IDS ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft mir, Schwachstellen in einem Netzwerk zu finden?', 4, '[{"text": "Nessus", "correct": true, "because": "Führt Schwachstellenscans durch"}, {"text": "Wireshark", "correct": false, "because": "Analysiert Pakete, nicht Schwachstellen"}, {"text": "PuTTY", "correct": false, "because": "Nur für Remote-Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Verschlüsselung die Datenintegrität allein sichert?', 3, '[{"text": "Nein", "correct": true, "because": "Hash-Funktionen sind zusätzlich nötig"}, {"text": "Ja", "correct": false, "because": "Schützt nur Vertraulichkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass statische IPs die Sicherheit erhöhen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Erleichtert Management, nicht Sicherheit"}, {"text": "Ja", "correct": false, "because": "Kein direkter Sicherheitsvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Brute-Force-Angriff immer langsam?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Rechenleistung"}, {"text": "Ja", "correct": false, "because": "Kann mit GPUs schnell sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario zeigt einen Insider-Angriff?', 4, '[{"text": "Mitarbeiter gibt Daten weiter", "correct": true, "because": "Interne Quelle der Bedrohung"}, {"text": "SQL-Injection von außen", "correct": false, "because": "Externer Angriff"}, {"text": "DDoS-Angriff", "correct": false, "because": "Zielt auf Verfügbarkeit"}]');
